private val pending = ConcurrentHashMap<String, CompletableDeferred<Reply>>()

suspend fun call(body: String): Reply {
    val id = UUID.randomUUID().toString()
    val deferred = CompletableDeferred<Reply>()
    pending[id] = deferred                       // register BEFORE send
    transport.send(Request(id, body))
    return try {
        withTimeout(5_000) { deferred.await() }  // cancellation frees the waiter
    } finally {
        pending.remove(id)                       // a late reply is then dropped
    }
}

fun onReply(reply: Reply) { pending.remove(reply.correlationId)?.complete(reply) }
